gaQ8(){return"\u0627\u0644\u0633\u0624\u0627\u0644 \u0627\u0644\u062a\u0627\u0644\u064a"},
gaQ0(){return"\u0627\u0643\u062a\u0645\u0644 \u0627\u0644\u0645\u0624\u062a\u0645\u0631"},
gaPZ(){return"\u0633\u062a\u0638\u0647\u0631 \u0625\u062c\u0627\u0628\u0627\u062a\u0643 \u063a\u062f\u064b\u0627 \u0641\u064a "},
gaQ_(){return" \u2014 \u062a\u0627\u0628\u0639 \u0631\u062f\u0648\u062f \u0641\u0639\u0644 \u0627\u0644\u062c\u0645\u0627\u0647\u064a\u0631 \u0647\u0646\u0627\u0643."},
gaQ4(){return"\u0625\u0644\u0649 \u0622\u062e\u0631 \u0627\u0644\u0623\u062e\u0628\u0627\u0631"},
gaTV(){return"\u0644\u0627 \u0631\u062c\u0639\u0629 \u0641\u064a\u0647"},
gaTW(){return"\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0625\u0639\u0644\u0627\u0646"},
gaTX(){return"\u0625\u0630\u0627 \u0648\u0631\u062f \u0639\u0631\u0636 \u0648\u0627\u062d\u062f \u0628\u0647\u0630\u0627 \u0627\u0644\u0633\u0639\u0631 \u064a\u064f\u0628\u0627\u0639 \u0627\u0644\u0644\u0627\u0639\u0628. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0633\u062d\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0646."},
